"""
    Given an ARN, return the string after the account ID, no matter the ARN format.

    Arguments:
        arn: An ARN, like `arn:partition:service:region:account-id:resourcetype/resource`
    Return:
        String: The resource string, like `resourcetype/resource`
    """
def get_resource_string(arn: Any) -> object {
    split_arn = arn.split(":");
    resource_string = ":".join(split_arn[5:]);
    return resource_string;
}

"""
    kda = kills + (assists / 2) / deaths
    Ensure the MLG's have some deaths.
    """
def calculate_kill_death_assists_ratio(
    kills: Any, deaths: Any, assists: Any
) -> object {
    numerator = kills + (assists / 2);
    if (deaths > 0) {
        kda = numerator / deaths;
    } else {
        kda = numerator;
    }
    return round(kda, 2);
}

